@page "/settings"
@using sv_faf34637247446f0b68246b5b3c2a94e.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section ? "active" : "")" @onclick="() => ActiveSection = section">
                    @section
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <p>Loading...</p>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </main>
</div>

@code {
    private readonly string[] _sections = { "Profile", "Notifications", "Security", "Appearance" };
    private string ActiveSection { get; set; } = "Profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    // Notifications
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = new() { "general", "announcements", "marketing", "engineering", "design" };
    private HashSet<string> _mutedChannels = new();

    // Security
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _revokeSessionId;
    private bool _showRevokeConfirm;

    // Appearance
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = { "Light", "Dark", "System" };
    private readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        SetProfileFields(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = notifs.EmailNotifications;
        _pushNotifications = notifs.PushNotifications;
        _weeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void SetProfileFields(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            SetProfileFields(_savedProfile);
    }

    // Notifications actions
    private void ToggleMuteChannel(string channel)
    {
        if (!_mutedChannels.Remove(channel))
            _mutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId)
    {
        _revokeSessionId = sessionId;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirm = false;
            _revokeSessionId = null;
            await ShowToast("Session revoked.");
        }
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _revokeSessionId = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // Render fragments
    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h3>Profile</h3>

            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" />
                <p class="avatar-url">@_avatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(channel)"
                               @onchange="() => ToggleMuteChannel(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h3>Security</h3>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="chevron">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor -->
            <div class="two-factor">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>Two-Factor Authentication</span>
                </label>
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="meta-info">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <!-- Active Sessions -->
            <h4>Active Sessions</h4>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_securitySettings?.Sessions is not null)
                    {
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session.Id != _securitySettings.Sessions.First().Id)
                                    {
                                        <button class="btn-danger btn-small" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>

            <!-- Revoke Confirmation Dialog -->
            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <p>Are you sure you want to revoke this session? The device will be logged out immediately.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="live-preview @(_theme.ToLower())-theme @(_compactMode ? "compact" : "")"
                 style="font-size: @GetPreviewFontSize()">
                <h4>Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
